import React from "react";
import { useLocation, useNavigate } from "react-router-dom";

export default function SuggestionPage() {
  const { state } = useLocation();
  const navigate = useNavigate();
  const data = state?.data || {};

  const lang = data.lang || "english";
  const details = data.symptom_details || [];
  const predictions = data.predictions || [];

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-2xl font-bold mb-4 text-center">Health Suggestions</h1>

      {/* Predicted Diseases */}
      <div className="bg-blue-50 p-4 rounded-xl mb-6">
        <h2 className="text-lg font-semibold mb-2">Possible Conditions:</h2>
        <ul className="list-disc pl-6">
          {predictions.map((p, i) => (
            <li key={i}>
              {p.disease} ({(p.score * 100).toFixed(1)}%)
            </li>
          ))}
        </ul>
      </div>

      {/* Symptom Advice */}
      {details.map((sym, index) => (
        <div key={index} className="mb-6 p-4 rounded-xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-semibold mb-2">
            {sym.symptom} {sym.symptom_kriol && `(${sym.symptom_kriol})`}
          </h3>
          <p className="text-gray-700">
            <strong>Description:</strong> {sym[lang]?.description || sym.en.description}
          </p>
          <p className="text-gray-700">
            <strong>Common Causes:</strong> {sym[lang]?.common_causes || sym.en.common_causes}
          </p>
          <p className="text-gray-700">
            <strong>Advice:</strong> {sym[lang]?.advice || sym.en.advice}
          </p>
        </div>
      ))}

      <button
        onClick={() => navigate(-1)}
        className="bg-gray-200 px-4 py-2 rounded-lg hover:bg-gray-300 mt-4"
      >
        ← Back
      </button>
    </div>
  );
}
